  /// </summary>
  /// <param name="strYearMonth"></param>
  /// <returns></returns>
  static CheckYearMonth6(e) {
    if (e.length == 0 || e == "无")
      return !0;
    if (e.length != 6) {
      const s = l(
        "年月:<{0}>长度不正确！应该为6位，但目前为:{1},不正确.",
        e,
        e.length
      );
      throw new Error(s);
    }
    const r = e.substring(0, 4);
    try {
      this.CheckYear(r);
    } catch (s) {
      const o = l(
        "年月:<{0}>中检查<年>:<{1}>不正确！错误：{2}",
        e,
        r,
        s
      );
      throw new Error(o);
    }
    const n = e.substring(4, 2);
    try {
      this.CheckMonth(n);
    } catch (s) {
      const o = l(
        "年月:<{0}>中检查<月>:<{1}>不正确！错误：{2}",
        e,
        n,
        s
      );
      throw new Error(o);
    }
    return !0;
  }
