  /// <summary>
  /// 检查年是否正确
  /// 日期：20140410
  /// 编写人：潘以锋
  /// </summary>
  /// <param name="strYear"></param>
  /// <returns></returns>
  static CheckYear(e) {
    if (e.length == 0)
      return !0;
    let r = 0;
    try {
      r = Number(e);
    } catch (n) {
      const s = l("<年>:<{0}>不正确！错误：{1}", e, n);
      throw new Error(s);
    }
    if (r < 1900) {
      const n = l("<年>:<{0}>小于1900,不正确！", r);
      throw new Error(n);
    }
    if (r > 3e3) {
      const n = l("<年>:<{0}>大于3000,不正确！", r);
      throw new Error(n);
    }
    return !0;
  }
