  /// 检查月是否正确
  /// 日期：20140410
  /// 编写人：潘以锋
  /// </summary>
  /// <param name="strMonth"></param>
  /// <returns></returns>
  static CheckMonth(e) {
    if (e.length == 0)
      return !0;
    let r = 0;
    try {
      r = Number(e);
    } catch (n) {
      const s = l("<月>:<{0}>不正确！错误：{1}", e, n);
      throw new Error(s);
    }
    if (r < 1) {
      const n = l("<月>:<{0}>小于1,不正确！", r);
      throw new Error(n);
    }
    if (r > 12) {
      const n = l("<月>:<{0}>大于12,不正确！", r);
      throw new Error(n);
    }
    return !0;
  }
